class Issue413 {
    static String loopWhile(String value, int len) {
        StringBuilder zeroes = new StringBuilder(); // <-- false positive, used in loop

        while (zeroes.length() + value.length() < len) {
            zeroes.append('0');
        }

        return zeroes.append(value).toString();
    }

    static String loopFor(String value, int len) {
        StringBuilder zeroes = new StringBuilder(); // <-- false positive, used in loop

        for (int i = 0; i < len - value.length(); i++) {
            zeroes.append("0");
        }

        return zeroes.append(value).toString();
    }

    static String loopStream(String value, int len) {
        return IntStream.range(0, len - value.length())
                .mapToObj(i -> "0")
                .collect(StringBuilder::new, StringBuilder::append, StringBuilder::append)
                .append("123").toString();
    }

    public static void main(String[] args) {
        System.out.println(loopWhile("123", 5));
        System.out.println(loopFor("123", 5));
        System.out.println(loopStream("123", 5));
    }
}
